namespace LibreWPF.Xaml.FSharp;

// What the generated C# keeps once per class (markup-extension application, dictionary loading, compiled-binding accessors), written once in F#.
internal static class XsgSupport
{
    public const string FileName = "0-XsgSupport.g.fs";

    public const string Text = """
        // <auto-generated by LibreWPF.Xaml.FSharp.Tool />
        namespace LibreWPF.Xaml.Generated

        open System

        [<Sealed>]
        type internal XsgExtensionServiceProvider(target: obj, prop: obj) =
            interface System.IServiceProvider with
                member this.GetService(serviceType: Type) : obj =
                    if serviceType = typeof<System.Windows.Markup.IProvideValueTarget> then box this else null
            interface System.Windows.Markup.IProvideValueTarget with
                member this.TargetObject = target
                member this.TargetProperty = prop

        /// The accessors a compiled binding hands to WPF as a property descriptor: typed, with no reflection over the source.
        [<Sealed>]
        type internal XsgCompiledProperty<'TOwner, 'TValue>(name: string, get: Func<'TOwner, 'TValue>, set: Action<'TOwner, 'TValue>) =
            inherit System.ComponentModel.PropertyDescriptor(name, null)
            override this.ComponentType = typeof<'TOwner>
            override this.PropertyType = typeof<'TValue>
            override this.IsReadOnly = isNull (box set)
            override this.CanResetValue(_component: obj) = false
            override this.ResetValue(_component: obj) = ()
            override this.ShouldSerializeValue(_component: obj) = false
            override this.GetValue(component: obj) : obj =
                match component with
                | :? 'TOwner as owner -> box (get.Invoke owner)
                | _ -> System.Windows.DependencyProperty.UnsetValue
            override this.SetValue(component: obj, value: obj) : unit =
                if isNull (box set) then raise (InvalidOperationException("'" + this.Name + "' is read-only."))
                match component with
                | :? 'TOwner as owner ->
                    set.Invoke(owner, unbox<'TValue> value)
                    this.OnValueChanged(component, EventArgs.Empty)
                | _ -> ()

        /// What the generated C# registers from a module initializer (RegisterComponent / RegisterDictionary): F# has none, so the class says it and
        /// XsgSupport.registerComponents registers them by reflection when the first generated class is constructed.
        [<AttributeUsage(AttributeTargets.Class, AllowMultiple = false)>]
        type internal XsgComponentAttribute(assembly: string, path: string, isDictionary: bool, isComponent: bool) =
            inherit Attribute()
            member _.Assembly = assembly
            member _.Path = path
            member _.IsDictionary = isDictionary
            member _.IsComponent = isComponent

        module internal XsgSupport =
            let private registered = System.Collections.Generic.HashSet<string>()

            /// Application.StartupUri, LoadComponent(Uri) and ResourceDictionary.Source find the generated classes of the assembly by their resource path.
            let registerComponents (assembly: System.Reflection.Assembly) : unit =
                let name = assembly.GetName().Name
                let first = lock registered (fun () -> registered.Add name)
                if first then
                    for t in assembly.GetTypes() do
                        match t.GetCustomAttributes(typeof<XsgComponentAttribute>, false) with
                        | [| :? XsgComponentAttribute as a |] ->
                            let owner = if String.IsNullOrEmpty a.Assembly then name else a.Assembly
                            let create = Func<obj>(fun () -> Activator.CreateInstance(t))
                            if a.IsComponent then System.Windows.Markup.XamlSourceGeneratedResources.RegisterComponent(owner, a.Path, create)
                            if a.IsDictionary then
                                System.Windows.Markup.XamlSourceGeneratedResources.RegisterDictionary(owner, a.Path, Func<System.Windows.ResourceDictionary>(fun () -> Activator.CreateInstance(t) :?> System.Windows.ResourceDictionary))
                        | _ -> ()

            /// The value of a markup extension written as an element of a collection or a resource.
            let provideValue (extension: System.Windows.Markup.MarkupExtension) : obj =
                extension.ProvideValue(XsgExtensionServiceProvider(extension, null))

            /// The same for an item of a collection: its owner and the collection are what the XAML reader reports as target (a Binding in MultiBinding.Bindings).
            let provideValueFor (extension: System.Windows.Markup.MarkupExtension, target: obj, collection: obj) : obj =
                extension.ProvideValue(XsgExtensionServiceProvider(target, collection))

            let private convert (propertyType: Type) (value: obj) : obj =
                match value with
                | :? string as text when not (propertyType.IsAssignableFrom(typeof<string>)) ->
                    System.ComponentModel.TypeDescriptor.GetConverter(propertyType).ConvertFromInvariantString(text)
                | _ -> value

            /// A project's own markup extension written as an attribute value: its value goes to the property (a binding it returns is set as one).
            let applyExtension (target: obj, dp: System.Windows.DependencyProperty, name: string, extension: System.Windows.Markup.MarkupExtension) : unit =
                let clr = if isNull dp then target.GetType().GetProperty(name) else null
                let provider = XsgExtensionServiceProvider(target, (if isNull dp then box clr else box dp))
                let value = extension.ProvideValue(provider)
                match target with
                | :? System.Windows.DependencyObject as d when not (isNull dp) ->
                    match value with
                    | :? System.Windows.Data.BindingBase as binding -> System.Windows.Data.BindingOperations.SetBinding(d, dp, binding) |> ignore
                    | _ -> d.SetValue(dp, convert dp.PropertyType value)
                | _ when not (isNull clr) -> clr.SetValue(target, convert clr.PropertyType value)
                | _ -> ()

            /// Source="x.xaml" of a dictionary this project does not generate (another assembly's, or a loose resource).
            let loadDictionary (assembly: string, path: string) : System.Windows.ResourceDictionary =
                let mutable dictionary : System.Windows.ResourceDictionary = null
                if System.Windows.Markup.XamlSourceGeneratedResources.TryCreateDictionary(assembly, path, &dictionary) then dictionary
                else System.Windows.ResourceDictionary(Source = Uri("/" + assembly + ";component/" + path, UriKind.Relative))
        """;
}
